import { existsSync } from 'node:fs';
import path from 'node:path';

/**
 * Resolves the project root identically under `mastra dev` and `mastra start`.
 *
 * Precedence:
 * 1. `PROJECT_ROOT` override — must be an existing directory containing a
 *    `package.json`; otherwise fail fast (the server refuses to boot rather
 *    than silently falling back).
 * 2. Walk-up from the start directory until a `package.json` appears, skipping
 *    any directory whose path contains a `.mastra` segment (its package.json
 *    is build-generated by `mastra build`, so `mastra start` would otherwise
 *    anchor inside the build output).
 * 3. Nothing found — throws.
 */
export function resolveProjectRoot(startDirectory: string) {
  const override = process.env.PROJECT_ROOT?.trim();
  if (override) {
    if (!existsSync(override)) {
      throw new Error(
        `PROJECT_ROOT is set to "${override}", but that directory does not exist. Fix the variable or unset it.`,
      );
    }
    if (!existsSync(path.join(override, 'package.json'))) {
      throw new Error(
        `PROJECT_ROOT is set to "${override}", but it contains no package.json. Point it at the project root or unset it.`,
      );
    }
    return path.resolve(override);
  }

  let currentDirectory = path.resolve(startDirectory);

  while (true) {
    const hasMastraSegment = currentDirectory.split(path.sep).includes('.mastra');
    if (!hasMastraSegment && existsSync(path.join(currentDirectory, 'package.json'))) {
      return currentDirectory;
    }

    const parentDirectory = path.dirname(currentDirectory);
    if (parentDirectory === currentDirectory) {
      throw new Error(`Could not find a package.json above ${startDirectory}.`);
    }

    currentDirectory = parentDirectory;
  }
}

export function resolveFromRoot(rootDirectory: string, inputPath: string) {
  const trimmedPath = inputPath.trim();
  const unquotedPath =
    trimmedPath.length >= 2 &&
    ((trimmedPath.startsWith('"') && trimmedPath.endsWith('"')) ||
      (trimmedPath.startsWith("'") && trimmedPath.endsWith("'")))
      ? trimmedPath.slice(1, -1)
      : trimmedPath;

  return path.resolve(rootDirectory, unquotedPath);
}

export function resolveWithinDirectory(directory: string, relativePath: string) {
  const resolvedDirectory = path.resolve(directory);
  const resolvedPath = path.resolve(resolvedDirectory, relativePath);
  const relativeResolvedPath = path.relative(resolvedDirectory, resolvedPath);

  if (
    relativeResolvedPath === '' ||
    relativeResolvedPath.startsWith(`..${path.sep}`) ||
    path.isAbsolute(relativeResolvedPath)
  ) {
    throw new Error('Path must remain within the allowed directory.');
  }

  return resolvedPath;
}
